I thought about this approach if it’s too expensive for the app to notify us about language changes.
Store the language in the cache along with the cached data, and drop the record if it doesn’t match the language of the request.
We don’t have to permanently store the language, but storing it in the cache is a small overhead.

So it could be something like this:

{noformat}public async setBusinessBillingProfileWithFieldsCache(
  ctx: Context,
  userId: number,
  language: string,
  profiles: BusinessBillingProfileWithFields
): Promise<void> {
  const cacheKey = WorkProfileCacheService.keyForBusinessBillingProfileWithFieldsCache(userId, language);
  return this.userBusinessBillingProfileWithFieldsCache.set(
    ctx, 
    cacheKey, 
    {
      metadata: {
        language
      }
      data: {
        profiles
      }
    }    
  );
}

public async getBusinessBillingProfileWithFieldsCache(
  ctx: Context,
  userId: number,
  language: string
): Promise<BusinessBillingProfileWithFields | null> {
  const cacheKey = WorkProfileCacheService.keyForBusinessBillingProfileWithFieldsCache(userId, language);
  const cached = this.userBusinessBillingProfileWithFieldsCache.get(ctx, cacheKey);
  if (!cached) {
    return null;
  }
  if (cached.metadata?.language !== language) {
    this.deleteBusinessBillingProfileWithFieldsCache(...);
    return null;
  }
  return cached.data;
}{noformat}

